-- Initial schema foundation only. Apply to local Supabase and test before any remote use.
create schema if not exists private;
create extension if not exists pgcrypto with schema extensions;
create type public.employee_role as enum ('cashier','supervisor','manager','administrator');
create type public.sale_status as enum ('pending','completed','voided','refunded','partially_refunded','pending_sync');
create type public.payment_method as enum ('cash','card','other');
create type public.payment_status as enum ('pending','confirmed','failed','unknown_offline','refunded','partially_refunded');
create type public.cash_session_status as enum ('open','closed','reconciled');
create type public.inventory_movement_type as enum ('sale','restock','adjustment','return','waste','opening_balance');
create table public.employee_profiles(id uuid primary key references auth.users(id) on delete restrict, employee_number text not null unique, display_name text not null, role public.employee_role not null default 'cashier', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table private.employee_credentials(employee_id uuid primary key references public.employee_profiles(id) on delete restrict, pin_hash text not null, failed_attempts integer not null default 0 check(failed_attempts>=0), locked_until timestamptz, pin_changed_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.sale_categories(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,active boolean not null default true,sort_order integer not null default 0);
create table public.ticket_types(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,description text,base_price_cents integer not null check(base_price_cents>=0),currency char(3) not null default 'ZAR' check(currency='ZAR'),active boolean not null default true,created_at timestamptz not null default now());
create table public.events(id uuid primary key default gen_random_uuid(),code text not null unique,name text not null,starts_at timestamptz not null,ends_at timestamptz not null,capacity integer check(capacity is null or capacity>=0),published boolean not null default false,check(ends_at>starts_at));
create table public.products(id uuid primary key default gen_random_uuid(),sku text not null unique,barcode text unique,name text not null,description text,category_id uuid references public.sale_categories(id) on delete restrict,unit_price_cents integer not null check(unit_price_cents>=0),currency char(3) not null default 'ZAR' check(currency='ZAR'),track_inventory boolean not null default false,stock_on_hand integer not null default 0 check(stock_on_hand>=0),reorder_level integer not null default 0 check(reorder_level>=0),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.price_rules(id uuid primary key default gen_random_uuid(),ticket_type_id uuid references public.ticket_types(id) on delete restrict,product_id uuid references public.products(id) on delete restrict,category_code text not null check(category_code in ('individual','group','school','event')),unit_price_cents integer not null check(unit_price_cents>=0),currency char(3) not null default 'ZAR' check(currency='ZAR'),valid_from timestamptz not null default now(),valid_until timestamptz,created_by uuid references public.employee_profiles(id) on delete restrict,check((ticket_type_id is not null)::integer+(product_id is not null)::integer=1),check(valid_until is null or valid_until>valid_from));
create table public.barcode_mappings(id uuid primary key default gen_random_uuid(),code text not null unique,product_id uuid references public.products(id) on delete restrict,ticket_type_id uuid references public.ticket_types(id) on delete restrict,active boolean not null default true,check((product_id is not null)::integer+(ticket_type_id is not null)::integer=1));
create table public.pos_devices(id uuid primary key default gen_random_uuid(),device_code text not null unique,display_name text not null,active boolean not null default true,last_seen_at timestamptz,created_at timestamptz not null default now());
create table public.cash_sessions(id uuid primary key default gen_random_uuid(),device_id uuid not null references public.pos_devices(id) on delete restrict,opened_by uuid not null references public.employee_profiles(id) on delete restrict,closed_by uuid references public.employee_profiles(id) on delete restrict,status public.cash_session_status not null default 'open',opening_float_cents integer not null check(opening_float_cents>=0),counted_cash_cents integer check(counted_cash_cents is null or counted_cash_cents>=0),expected_cash_cents integer check(expected_cash_cents is null or expected_cash_cents>=0),variance_cents integer,opened_at timestamptz not null default now(),closed_at timestamptz,reconciled_at timestamptz,check((status='open' and closed_at is null) or status<>'open'));
create unique index one_open_cash_session_per_device on public.cash_sessions(device_id) where status='open';
create table public.sales(id uuid primary key default gen_random_uuid(),receipt_number text unique,device_id uuid not null references public.pos_devices(id) on delete restrict,cash_session_id uuid references public.cash_sessions(id) on delete restrict,cashier_id uuid not null references public.employee_profiles(id) on delete restrict,client_transaction_id uuid not null,idempotency_key text not null unique,status public.sale_status not null default 'pending',currency char(3) not null default 'ZAR' check(currency='ZAR'),subtotal_cents integer not null check(subtotal_cents>=0),tax_cents integer not null default 0 check(tax_cents>=0),discount_cents integer not null default 0 check(discount_cents>=0),total_cents integer not null check(total_cents>=0),tax_treatment text not null default 'unconfigured' check(tax_treatment in ('unconfigured','exclusive','inclusive','exempt','zero_rated','not_applicable')),offline_created_at timestamptz,created_at timestamptz not null default now(),completed_at timestamptz,unique(device_id,client_transaction_id),check(total_cents=subtotal_cents+tax_cents-discount_cents),check(discount_cents<=subtotal_cents+tax_cents));
create table public.group_details(sale_id uuid primary key references public.sales(id) on delete restrict,group_name text,group_type text not null check(group_type in ('group','school','event')),headcount integer not null check(headcount>0),contact_name text,contact_reference text);
create table public.sale_items(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id) on delete restrict,product_id uuid references public.products(id) on delete restrict,ticket_type_id uuid references public.ticket_types(id) on delete restrict,item_name_snapshot text not null,item_code_snapshot text not null,quantity integer not null check(quantity>0),unit_price_cents integer not null check(unit_price_cents>=0),tax_cents integer not null default 0 check(tax_cents>=0),discount_cents integer not null default 0 check(discount_cents>=0),line_total_cents integer not null check(line_total_cents>=0),check((product_id is not null)::integer+(ticket_type_id is not null)::integer=1),check(line_total_cents=unit_price_cents*quantity+tax_cents-discount_cents),check(discount_cents<=unit_price_cents*quantity+tax_cents));
create table public.payments(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id) on delete restrict,method public.payment_method not null,status public.payment_status not null default 'pending',amount_cents integer not null check(amount_cents>0),currency char(3) not null default 'ZAR' check(currency='ZAR'),terminal_reference text,provider_reference text,recorded_by uuid not null references public.employee_profiles(id) on delete restrict,confirmed_at timestamptz,created_at timestamptz not null default now(),check(method<>'card' or status in ('pending','failed','unknown_offline') or coalesce(nullif(terminal_reference,''),nullif(provider_reference,'')) is not null));
create table public.issued_tickets(id uuid primary key default gen_random_uuid(),sale_item_id uuid not null references public.sale_items(id) on delete restrict,ticket_type_id uuid not null references public.ticket_types(id) on delete restrict,ticket_code text not null unique default encode(extensions.gen_random_bytes(16),'hex'),barcode text not null unique default encode(extensions.gen_random_bytes(16),'hex'),status text not null default 'valid' check(status in ('valid','redeemed','voided','refunded')),issued_at timestamptz not null default now(),redeemed_at timestamptz,redeemed_by uuid references public.employee_profiles(id) on delete restrict);
create table public.inventory_movements(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete restrict,sale_item_id uuid references public.sale_items(id) on delete restrict,movement_type public.inventory_movement_type not null,quantity_delta integer not null check(quantity_delta<>0),reason text,created_by uuid references public.employee_profiles(id) on delete restrict,created_at timestamptz not null default now());
create table public.cash_movements(id uuid primary key default gen_random_uuid(),cash_session_id uuid not null references public.cash_sessions(id) on delete restrict,movement_type text not null check(movement_type in ('cash_sale','refund','paid_in','paid_out','float_adjustment')),amount_cents integer not null check(amount_cents>0),reference text,created_by uuid not null references public.employee_profiles(id) on delete restrict,created_at timestamptz not null default now());
create table public.refunds(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id) on delete restrict,requested_by uuid not null references public.employee_profiles(id) on delete restrict,approved_by uuid references public.employee_profiles(id) on delete restrict,amount_cents integer not null check(amount_cents>0),reason text not null,status text not null default 'pending' check(status in ('pending','approved','rejected','completed')),created_at timestamptz not null default now(),completed_at timestamptz,check(approved_by is null or approved_by<>requested_by));
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references public.employee_profiles(id) on delete restrict,action text not null,entity_type text not null,entity_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.offline_sync_records(id uuid primary key default gen_random_uuid(),device_id uuid not null references public.pos_devices(id) on delete restrict,client_transaction_id uuid not null,idempotency_key text not null unique,status text not null default 'queued' check(status in ('queued','processing','synced','conflict','failed')),error_code text,created_at timestamptz not null default now(),synced_at timestamptz,unique(device_id,client_transaction_id));
insert into public.sale_categories(code,name,sort_order) values('individual','Individual admission',10),('group','Group admission',20),('school','School visit',30),('event','Events',40);
insert into public.ticket_types(code,name,description,base_price_cents) values('adult','Adult admission','Draft price; confirm before real sales',6000),('child','Child admission','Draft price; confirm before real sales',4000);
insert into public.price_rules(ticket_type_id,category_code,unit_price_cents) select id,'individual',base_price_cents from public.ticket_types where code in ('adult','child');
insert into public.barcode_mappings(code,ticket_type_id) select 'TKT-'||upper(code),id from public.ticket_types where code in ('adult','child');
do $$ declare t record; begin for t in select tablename from pg_tables where schemaname='public' loop execute format('alter table public.%I enable row level security',t.tablename); end loop; end $$;
create policy "own employee profile" on public.employee_profiles for select to authenticated using(id=auth.uid());
create policy "read active categories" on public.sale_categories for select to authenticated using(active=true);
create policy "read active ticket types" on public.ticket_types for select to authenticated using(active=true);
create policy "read active products" on public.products for select to authenticated using(active=true);
create policy "read published events" on public.events for select to authenticated using(published=true);
create policy "read active barcode mappings" on public.barcode_mappings for select to authenticated using(active=true);
revoke all on schema private from public,anon,authenticated;
revoke all on all tables in schema private from public,anon,authenticated;
grant usage on schema private to service_role;
grant all on all tables in schema private to service_role;
alter default privileges in schema private revoke all on tables from public,anon,authenticated;
revoke all on all tables in schema public from anon,authenticated;
grant select on public.employee_profiles,public.sale_categories,public.ticket_types,public.products,public.events,public.barcode_mappings to authenticated;
grant select,insert,update,delete on all tables in schema public to service_role;
grant usage,select on all sequences in schema public to service_role;
-- No checkout/stock/refund RPCs yet: this is deliberately not a production transaction system.
